package com.wittywilla.wittymediaclient.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.graphics.vector.group
import androidx.compose.ui.unit.dp

// The icons in docs/APP-DESIGN.md, "Icons" and "You and settings": Material Symbols, rounded, weight 400, from
// github.com/google/material-design-icons (Apache-2.0). Drawn on their 960 grid, which starts at -960.
private fun symbol(name: String, path: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f)
        .group(translationY = 960f) { addPath(addPathNodes(path), fill = SolidColor(Color.Black)) }
        .build()

// The few that are only published on the older 24 grid.
private fun symbol24(name: String, path: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
        .addPath(addPathNodes(path), fill = SolidColor(Color.Black))
        .build()

